create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',phone text not null default '',role text not null default 'user' check(role in('user','admin')),created_at timestamptz not null default now());
create table if not exists public.wallets(user_id uuid primary key references auth.users(id) on delete cascade,currency text not null default 'GHS' check(currency='GHS'),available_balance numeric(14,2) not null default 0 check(available_balance>=0),reserved_balance numeric(14,2) not null default 0 check(reserved_balance>=0),updated_at timestamptz not null default now());
create table if not exists public.ledger_entries(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),entry_type text not null,amount numeric(14,2) not null check(amount>0),currency text not null default 'GHS' check(currency='GHS'),direction text not null check(direction in('credit','debit')),status text not null default 'posted' check(status in('pending','posted','reversed')),reference text unique,related_id uuid,description text not null default '',created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.deposits(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),amount numeric(14,2) not null check(amount>0),currency text not null default 'GHS' check(currency='GHS'),reference text not null unique,paystack_reference text unique,status text not null default 'pending' check(status in('pending','success','failed')),verified_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.withdrawals(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),amount numeric(14,2) not null check(amount>0),currency text not null default 'GHS' check(currency='GHS'),method text not null check(method in('mtn_momo','telecel_cash','at_money','bank')),account_name text not null,account_number text not null,bank_name text,status text not null default 'pending' check(status in('pending','approved','completed','rejected')),payout_reference text,admin_note text,reviewed_by uuid references auth.users(id),reviewed_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.investment_projects(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,category text not null,description text not null default '',min_amount numeric(14,2) not null default 20 check(min_amount>0),max_amount numeric(14,2) not null default 1000 check(max_amount>=min_amount),duration_days integer,published boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.investment_orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),project_id uuid not null references public.investment_projects(id),amount numeric(14,2) not null check(amount>0),status text not null default 'pending_review' check(status in('pending_review','active','completed','cancelled')),terms_version text not null default 'v1',created_at timestamptz not null default now());
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users(id),action text not null,entity_type text not null,entity_id text,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists ledger_user_created_idx on public.ledger_entries(user_id,created_at desc); create index if not exists deposits_user_created_idx on public.deposits(user_id,created_at desc); create index if not exists withdrawals_user_created_idx on public.withdrawals(user_id,created_at desc);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,phone) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),coalesce(new.phone,'')) on conflict(id) do nothing; insert into public.wallets(user_id) values(new.id) on conflict(user_id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created_agri on auth.users; create trigger on_auth_user_created_agri after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; alter table public.wallets enable row level security; alter table public.ledger_entries enable row level security; alter table public.deposits enable row level security; alter table public.withdrawals enable row level security; alter table public.investment_projects enable row level security; alter table public.investment_orders enable row level security; alter table public.audit_logs enable row level security;
create policy "profile self read" on public.profiles for select to authenticated using(id=auth.uid()); create policy "profile self update safe" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid() and role='user'); create policy "wallet self read" on public.wallets for select to authenticated using(user_id=auth.uid()); create policy "ledger self read" on public.ledger_entries for select to authenticated using(user_id=auth.uid()); create policy "deposits self read" on public.deposits for select to authenticated using(user_id=auth.uid()); create policy "withdrawals self read" on public.withdrawals for select to authenticated using(user_id=auth.uid()); create policy "projects public read" on public.investment_projects for select to anon,authenticated using(published=true); create policy "investment orders self read" on public.investment_orders for select to authenticated using(user_id=auth.uid());
insert into public.investment_projects(slug,name,category,description,min_amount,max_amount) values('poultry-starter','Poultry Starter','Poultry','Agricultural poultry project. Review the project terms and risks before committing funds.',20,1000),('boer-goat','Boer Goat','Livestock','Boer goat farming project. Project-specific terms and risks must be provided before launch.',20,1000),('dairy-cow','Dairy Cow','Livestock','Dairy cattle project. No earnings are promised or credited automatically.',20,1000) on conflict(slug) do nothing;
create or replace function public.credit_verified_deposit(p_user_id uuid,p_amount numeric,p_reference text,p_description text) returns void language plpgsql security definer set search_path=public as $$ begin if p_amount<=0 then raise exception 'Invalid amount'; end if; if exists(select 1 from public.ledger_entries where reference=p_reference) then return; end if; update public.wallets set available_balance=available_balance+p_amount,updated_at=now() where user_id=p_user_id; if not found then raise exception 'Wallet not found'; end if; insert into public.ledger_entries(user_id,entry_type,amount,direction,status,reference,description) values(p_user_id,'deposit',p_amount,'credit','posted',p_reference,p_description); end; $$;
create or replace function public.request_withdrawal(p_user_id uuid,p_amount numeric,p_method text,p_account_name text,p_account_number text,p_bank_name text) returns jsonb language plpgsql security definer set search_path=public as $$ declare wid uuid; begin if p_amount<=0 then raise exception 'Invalid amount'; end if; update public.wallets set available_balance=available_balance-p_amount,reserved_balance=reserved_balance+p_amount,updated_at=now() where user_id=p_user_id and available_balance>=p_amount; if not found then raise exception 'Insufficient available balance'; end if; insert into public.withdrawals(user_id,amount,method,account_name,account_number,bank_name,status) values(p_user_id,p_amount,p_method,p_account_name,p_account_number,nullif(p_bank_name,''),'pending') returning id into wid; insert into public.ledger_entries(user_id,entry_type,amount,direction,status,related_id,description) values(p_user_id,'withdrawal_reserve',p_amount,'debit','posted',wid,'Funds reserved for withdrawal request'); return jsonb_build_object('id',wid,'status','pending'); end; $$;
create or replace function public.complete_manual_withdrawal(p_withdrawal_id uuid,p_admin_id uuid,p_payout_reference text) returns jsonb language plpgsql security definer set search_path=public as $$ declare w public.withdrawals%rowtype; begin select * into w from public.withdrawals where id=p_withdrawal_id for update; if not found or w.status not in('approved','pending') then raise exception 'Withdrawal cannot be completed'; end if; if length(trim(p_payout_reference))<4 then raise exception 'Payout reference required'; end if; update public.wallets set reserved_balance=reserved_balance-w.amount,updated_at=now() where user_id=w.user_id and reserved_balance>=w.amount; if not found then raise exception 'Reserved balance mismatch'; end if; update public.withdrawals set status='completed',payout_reference=p_payout_reference,reviewed_by=p_admin_id,reviewed_at=coalesce(reviewed_at,now()),completed_at=now() where id=w.id; insert into public.ledger_entries(user_id,entry_type,amount,direction,status,reference,related_id,description,created_by) values(w.user_id,'withdrawal_paid',w.amount,'debit','posted','PAYOUT-'||p_payout_reference,w.id,'Manual payout recorded',p_admin_id); return jsonb_build_object('id',w.id,'status','completed','payout_reference',p_payout_reference); end; $$;
create or replace function public.reject_withdrawal_release_funds(p_withdrawal_id uuid,p_admin_id uuid,p_note text) returns jsonb language plpgsql security definer set search_path=public as $$ declare w public.withdrawals%rowtype; begin select * into w from public.withdrawals where id=p_withdrawal_id for update; if not found or w.status not in('pending','approved') then raise exception 'Withdrawal cannot be rejected'; end if; update public.wallets set available_balance=available_balance+w.amount,reserved_balance=reserved_balance-w.amount,updated_at=now() where user_id=w.user_id and reserved_balance>=w.amount; if not found then raise exception 'Reserved balance mismatch'; end if; update public.withdrawals set status='rejected',admin_note=p_note,reviewed_by=p_admin_id,reviewed_at=now() where id=w.id; insert into public.ledger_entries(user_id,entry_type,amount,direction,status,related_id,description,created_by) values(w.user_id,'withdrawal_release',w.amount,'credit','posted',w.id,'Reserved funds released after rejection',p_admin_id); return jsonb_build_object('id',w.id,'status','rejected'); end; $$;
revoke all on function public.credit_verified_deposit(uuid,numeric,text,text) from public,anon,authenticated; revoke all on function public.request_withdrawal(uuid,numeric,text,text,text,text) from public,anon,authenticated; revoke all on function public.complete_manual_withdrawal(uuid,uuid,text) from public,anon,authenticated; revoke all on function public.reject_withdrawal_release_funds(uuid,uuid,text) from public,anon,authenticated; grant execute on function public.credit_verified_deposit(uuid,numeric,text,text) to service_role; grant execute on function public.request_withdrawal(uuid,numeric,text,text,text,text) to service_role; grant execute on function public.complete_manual_withdrawal(uuid,uuid,text) to service_role; grant execute on function public.reject_withdrawal_release_funds(uuid,uuid,text) to service_role;
